command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: FRIEDVOLLE AURA (V13 Ready - Ehrenschulden Layout)
// ==========================================

(async () => {
    // ============================================================
    // 0. Framework laden & Wirkungsende-Hook registrieren
    // ============================================================
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) {
        await fwMacro.execute();
    }

    if (typeof DSK === "undefined") {
        ui.notifications.error("Das DSK-Framework konnte nicht geladen werden!");
        return;
    }
    const DSK_FW = globalThis.DSK || DSK;

    const gabenName = "Friedvolle Aura (Nurti)";
    const ahne = "nurti";

    const getOwners = (act) => {
        if (!act) return [];
        const ownership = act.ownership || act.permission || {};
        return Object.entries(ownership).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);
    };

    if (DSK_FW.EffektEnde) {
        DSK_FW.EffektEnde.Register("nurtiFriedvolleAura", gabenName, "Die friedvolle Aura verblasst, und die Modifikatoren sind aufgehoben.");
    }

    // ============================================================
    // 1. Initialisierung & Caster-Ermittlung
    // ============================================================
    const casterActor = (typeof testData !== "undefined" && testData?.actor) || 
                        (typeof testData !== "undefined" && testData?.speaker?.actor ? game.actors.get(testData.speaker.actor) : null) || 
                        (typeof testData !== "undefined" && testData?.speaker?.token ? canvas.tokens.get(testData.speaker.token)?.actor : null) || 
                        actor || 
                        canvas.tokens.controlled[0]?.actor || 
                        game.user.character;

    if (!casterActor) {
        ui.notifications.warn("Kein Akteur gefunden! Bitte wähle deinen Token aus.");
        return;
    }

    let qs = casterActor.getFlag("world", "letzteGabenQS") || 1;
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");

    try {
        if (typeof testData !== "undefined" && testData) {
            const parsedQs = Number(testData?.result?.QL || testData?.qualityStep);
            if (!isNaN(parsedQs) && parsedQs > 0) qs = parsedQs;
        }
    } catch (e) {}

    // ============================================================
    // 2. Ziele sammeln (Jeder im Target ist ein Angreifer!)
    // ============================================================
    const targets = Array.from(game.user.targets);
    let zielAkteure = [];

    if (targets.length > 0) {
        for (let t of targets) {
            if (t.actor && t.actor.id !== casterActor.id) {
                zielAkteure.push({ actor: t.actor, name: t.name });
            }
        }
    }

    if (zielAkteure.length === 0) {
        return ui.notifications.warn("Luna sagt 🌙: Bitte wähle mindestens ein Ziel (die Angreifer) per Target aus!");
    }

    const malusWillenskraft = qs * 4;
    const malusAngriff = qs;
    const dauerRunden = qs * 3;

    const thinStyle = 'style="font-weight: 300; font-size: 0.9em; opacity: 0.8;"';
    const willCalc = `<span ${thinStyle}>(${qs} QS x 4)</span>`;
    const atkCalc = `<span ${thinStyle}>(${qs} QS)</span>`;

    const basisBeschreibung = `Um das Nurtikind anzugreifen, muss der Angreifer eine um ${malusWillenskraft} ${willCalc} erschwerte Probe auf Willenskraft ablegen. Gelingt diese nicht, kann er es nicht angreifen. Gelingt ihm dies, sind Attacken gegen das Nurtikind dennoch um ${malusAngriff} ${atkCalc} erschwert.<br><br><b>Achtung:</b><br>Führt das Nurtikind während der Wirkungsdauer Angriffe oder sonstige offensive Handlungen gegen seine Feinde aus, bricht die Wirkung der Gabe ab.`;
    const dauerText = `${dauerRunden} Kampfrunden`;
    const casterName = DSK_FW.ResolveTokenName(casterActor);

    let erfolgreicheNamen = [];
    let erfolgsZiele = [];
    let fehlschlagZiele = []; 

    // ============================================================
    // 3. EFFEKTE ANLEGEN (Ziele = Debuff, Caster = Info-Marker)
    // ============================================================
    for (let z of zielAkteure) {
        const effektNameZiel = `${gabenName} - Aura von ${casterName}`;
        const beschreibungZiel = `${basisBeschreibung}<br><hr><b>Aura wirkt von:</b> ${casterName}`;

        try {
            let alterZielEffekt = z.actor.effects.find(e => e.name === effektNameZiel);
            if (alterZielEffekt) await alterZielEffekt.delete();

            await DSK_FW.Effekt.Anwenden({
                name: effektNameZiel,
                ahne: ahne,
                beschreibung: beschreibungZiel,
                gabeZiel: "", // Kein Wesens-Filter!
                qs: qs,
                ziel: z.actor
            });

            const eff = z.actor.effects.find(e => e.name === effektNameZiel);
            if (eff) {
                await eff.update({
                    duration: { rounds: dauerRunden },
                    changes: [
                        { key: "system.skillModifiers.FW", mode: 0, value: `Willenskraft -${malusWillenskraft}`, priority: 20 },
                        { key: "system.meleeStats.attack", mode: 2, value: -malusAngriff, priority: 20 },
                        { key: "system.rangeStats.attack", mode: 2, value: -malusAngriff, priority: 20 }
                    ]
                });
            }
            erfolgreicheNamen.push(z.name);
        } catch (e) {
            console.warn("Effekt für Ziel konnte nicht angewendet werden:", e);
            fehlschlagZiele.push({ name: z.name, grund: "Fehler beim Anlegen" });
        }
    }

    // --- SAMMEL-EFFEKT FÜR DEN CASTER ---
    if (erfolgreicheNamen.length > 0) {
        const alleNamenStr = erfolgreicheNamen.join(", ");
        const effektNameCaster = `${gabenName} - Wirkt gegen: ${alleNamenStr}`;
        const beschreibungCaster = `${basisBeschreibung}<br><hr><b>Aura wirkt gegen:</b><br>${erfolgreicheNamen.map(n => `• ${n}`).join("<br>")}`;

        try {
            // Lösche alle alten Sammel-Effekte der Aura auf dem Caster
            let alteCasterEffekte = casterActor.effects.filter(e => e.name.includes(gabenName));
            for(let e of alteCasterEffekte) await e.delete();

            await DSK_FW.Effekt.Anwenden({
                name: effektNameCaster,
                ahne: ahne,
                beschreibung: beschreibungCaster,
                gabeZiel: "",
                qs: qs,
                ziel: casterActor
            });

            const effC = casterActor.effects.find(e => e.name === effektNameCaster);
            if (effC) {
                await effC.update({ duration: { rounds: dauerRunden }});
            }

            erfolgsZiele.push(casterName); // Nurtikind zuerst
            erfolgsZiele.push(...erfolgreicheNamen); // Dann die Angreifer
        } catch (e) {
            console.warn("Effekt für Caster konnte nicht angewendet werden:", e);
        }
    }

    // --- FLAG-CLEANUP (Nur bei Erfolg) ---
    if (erfolgreicheNamen.length > 0) {
        await casterActor.unsetFlag("world", "letzteGabenQS");
        await casterActor.unsetFlag("world", "letzteGabenMessageId");
    }

    // ============================================================
    // 4. WHISPER-EMPFÄNGER & GEFÜSTERTE CHATKARTE ERSTELLEN
    // ============================================================
    let ownerIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
    getOwners(casterActor).forEach(id => ownerIds.add(id));
    zielAkteure.forEach(z => {
        getOwners(z.actor).forEach(id => ownerIds.add(id));
    });
    const whisperEmpfaenger = Array.from(ownerIds).filter(id => game.users.get(id));

    let erfolgHtml = "";
    if (erfolgsZiele.length > 0) {
        erfolgHtml = `
            <p><span style="color:#18940F; font-weight:bold;">Erfolg</span></p>
            <p style="font-weight:bold; color:#000; margin: 4px 0 2px 0;">Aura wirkt gegen:</p>
            <ul class="dsklist" style="font-weight:normal; margin-top:4px;">
                ${erfolgsZiele.map(n => `<li>${n}</li>`).join("")}
            </ul>
        `;
    }

    let fehlschlagHtml = "";
    if (fehlschlagZiele.length > 0) {
        const grouped = {};
        for (const f of fehlschlagZiele) {
            if (!grouped[f.grund]) grouped[f.grund] = [];
            grouped[f.grund].push(f.name);
        }

        let fehlschlagInhalt = "";
        for (const [grund, namen] of Object.entries(grouped)) {
            fehlschlagInhalt += `
                <p style="font-weight:normal; color:#000; margin: 4px 0 2px 0;">(${grund})</p>
                <ul class="dsklist" style="font-weight:normal; margin-top:0;">
                    ${namen.map(n => `<li>${n}</li>`).join("")}
                </ul>
            `;
        }

        fehlschlagHtml = `
            <hr>
            <p><span style="color:#B30000; font-weight:bold;">Fehlschlag</span></p>
            ${fehlschlagInhalt}
        `;
    }

    const cardContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header("Friedvolle Aura", DSK_FW.Symbol(ahne))}
            <div class="dskbox2" style="margin-top:10px;">
                <p><b>Gabenwirkung:</b></p>
                <p>${basisBeschreibung}</p>
                <hr>
                ${erfolgHtml}
                ${fehlschlagHtml}
                <hr>
                <p style="text-align:center; font-weight:bold;">
                    Wirkungsdauer: ${dauerText}
                </p>
            </div>
        </div>
    `;

    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
    if (msg) {
        await msg.update({ content: cardContent });
    } else {
        const neueMsg = await ChatMessage.create({
            speaker: { alias: "System" },
            whisper: whisperEmpfaenger,
            content: cardContent
        });
        if (neueMsg && fehlschlagZiele.length > 0 && erfolgreicheNamen.length === 0) {
            await casterActor.setFlag("world", "letzteGabenMessageId", neueMsg.id);
        }
    }
})();
